using System.Diagnostics;
using System.Windows;
using System.Windows.Controls;
using SE.Roleplay.Launcher.Models;
using SE.Roleplay.Launcher.Services;
namespace SE.Roleplay.Launcher;
public partial class MainWindow : Window { private readonly SettingsStore _settingsStore = new(); private readonly ServerDirectoryClient _directoryClient = new(); private LauncherSettings _settings = new(); public MainWindow() { InitializeComponent(); Loaded += MainWindow_Loaded; } private async void MainWindow_Loaded(object sender, RoutedEventArgs e) { _settings = await _settingsStore.LoadAsync(); DirectoryUrlBox.Text = _settings.ServerDirectoryUrl; SteamAppIdBox.Text = _settings.SteamAppId; if (!string.IsNullOrWhiteSpace(_settings.ServerDirectoryUrl)) await LoadServersAsync(); } private void ShowServers_Click(object sender, RoutedEventArgs e) => ShowPage("servers"); private void ShowConnect_Click(object sender, RoutedEventArgs e) => ShowPage("connect"); private void ShowSettings_Click(object sender, RoutedEventArgs e) => ShowPage("settings"); private void ShowPage(string page) { ServersPanel.Visibility = page == "servers" ? Visibility.Visible : Visibility.Collapsed; ConnectPanel.Visibility = page == "connect" ? Visibility.Visible : Visibility.Collapsed; SettingsPanel.Visibility = page == "settings" ? Visibility.Visible : Visibility.Collapsed; PageEyebrow.Text = page switch { "connect" => "QUICK JOIN", "settings" => "PREFERENCES", _ => "COMMUNITY" }; PageTitle.Text = page switch { "connect" => "Join a server.", "settings" => "Make it yours.", _ => "Find your next story." }; PageSubtitle.Text = page switch { "connect" => "Enter a server endpoint and hand off the connection to Steam.", "settings" => "Configure the community directory and game launch integration.", _ => "Browse roleplay communities or connect directly to a server." }; } private async void RefreshServers_Click(object sender, RoutedEventArgs e) => await LoadServersAsync(); private async Task LoadServersAsync() { if (string.IsNullOrWhiteSpace(_settings.ServerDirectoryUrl)) { ServerList.ItemsSource = null; EmptyServersPanel.Visibility = Visibility.Visible; ServerCountText.Text = "DIRECTORY NOT CONFIGURED"; StatusText.Text = "Add a server directory URL in Settings."; return; } try { StatusText.Text = "Refreshing server directory…"; var servers = await _directoryClient.GetServersAsync(_settings.ServerDirectoryUrl); ServerList.ItemsSource = servers; EmptyServersPanel.Visibility = servers.Count == 0 ? Visibility.Visible : Visibility.Collapsed; ServerCountText.Text = $"{servers.Count} SERVER(S)"; StatusText.Text = $"Directory updated. {servers.Count} server(s) listed."; } catch (Exception ex) { ServerList.ItemsSource = null; EmptyServersPanel.Visibility = Visibility.Visible; ServerCountText.Text = "DIRECTORY UNAVAILABLE"; StatusText.Text = ex.Message; } } private async void SaveSettings_Click(object sender, RoutedEventArgs e) { var appId = SteamAppIdBox.Text.Trim(); if (string.IsNullOrWhiteSpace(appId) || appId.Any(c => !char.IsDigit(c))) { StatusText.Text = "Steam App ID must contain digits only."; return; } _settings.ServerDirectoryUrl = DirectoryUrlBox.Text.Trim(); _settings.SteamAppId = appId; await _settingsStore.SaveAsync(_settings); StatusText.Text = "Settings saved."; await LoadServersAsync(); } private void ServerList_SelectionChanged(object sender, SelectionChangedEventArgs e) { if (ServerList.SelectedItem is not ServerEntry server) return; AddressBox.Text = server.Address; PortBox.Text = server.Port.ToString(); ShowPage("connect"); } private void Connect_Click(object sender, RoutedEventArgs e) { var host = AddressBox.Text.Trim(); if (host.Length == 0 || host.Any(char.IsWhiteSpace) || !(Uri.CheckHostName(host) is UriHostNameType.Dns or UriHostNameType.IPv4 or UriHostNameType.IPv6)) { StatusText.Text = "Enter a valid server IP address or hostname."; return; } if (!int.TryParse(PortBox.Text.Trim(), out var port) || port is < 1 or > 65535) { StatusText.Text = "Port must be between 1 and 65535."; return; } var endpointHost = host.Contains(':') && !host.StartsWith("[", StringComparison.Ordinal) ? $"[{host}]" : host; var uri = $"steam://connect/{endpointHost}:{port}"; try { Process.Start(new ProcessStartInfo(uri) { UseShellExecute = true }); StatusText.Text = $"Handed {endpointHost}:{port} to Steam."; } catch (Exception ex) { StatusText.Text = $"Could not open Steam: {ex.Message}"; } } }